INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,status,url_slug,created_at,updated_at) VALUES
('fear','Fear','townsfolk','Moll',NULL,NULL,'Emotions','{"slug":"fear","name":"Fear","team":"townsfolk","ability":"You start knowing a player: they''re drunk & get false info.","creator":"Moll","appearsIn":"Emotions","lede":"Fear knows what haunts them.","howToRun":["During setup, mark a player Scared, they are drunk & whenever they learn any information from their ability, it must be false.","On the first night, wake the Fear. Point to the player marked Scared. Put the Fear to sleep."],"examples":["Hobbe is Fear & learns Jasper the Guilt. On the first night Jasper chooses Happiness which is in play, but learns a no, as they have to get false info."],"firstNight":35,"firstNightReminder":"Point to the player marked Scared.","otherNight":0,"reminders":["Scared"],"setup":false,"special":[{"type":"selection","name":"bag-duplicate"}],"image":"https://user-images.klutzbanana.com/si39fypmwwia6ufcm7f805td.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/i531ytrpls4vcgzfrab91h58.png","tips":["I advice against making the Demon drunk. With Faith & Hope it can be fine to do."]}','published','emotions/fear',datetime('now'),datetime('now')),
('guilt','Guilt','townsfolk','Moll',NULL,NULL,'Emotions','{"slug":"guilt","name":"Guilt","team":"townsfolk","ability":"Each night, choose an evil character, you learn if it is in play.","creator":"Moll","appearsIn":"Emotions","lede":"Guilt knows things.","howToRun":["Each night, wake Guilt. They point at any Minion or Demon character icon on their character sheet. If it''s in-play nod your head yes. If it is not-in play-shake your head no. Put Guilt to sleep."],"examples":["Syddanus is Happiness. On the first night Guilt chooses Happiness and learns yes, because Happiness is in play.","Audee is Excitement. On the first night Audee chooses the Guilt player. Guilt chooses Excitement and learns a no, because Excitement makes them have to get false information, and Excitement is in play.","Jasper is Faith who thinks they are Guilt. On the second night Jasper chooses Faith, and learns no, since they can get any information."],"firstNight":74,"firstNightReminder":"Guilt points towards an evil character. Nod ''yes'' or shake head ''no'' for whether it is in play.","otherNight":86,"otherNightReminder":"Guilt points towards an evil character. Nod ''yes'' or shake head ''no'' for whether it is in play.","setup":false,"special":[{"type":"selection","name":"bag-duplicate"}],"image":"https://user-images.klutzbanana.com/n01xhnzy8ieq5mw0jnpnvwos.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/n6ozcvnz2ij7yqdbyy4o1x4v.png"}','published','emotions/guilt',datetime('now'),datetime('now')),
('anxiety','Anxiety','townsfolk','Moll',NULL,NULL,'Emotions','{"slug":"anxiety","name":"Anxiety","team":"townsfolk","ability":"Each night, you learn a character type no Demon has as an alive neighbour (not Travellers).","creator":"Moll","appearsIn":"Emotions","lede":"Anxiety knows a place they feel safer in.","howToRun":["Each night, wake Anxiety. Point to a character type on their character sheet. There is no Demon with that character type as their alive neighbour. Put Anxiety to sleep."],"examples":["Sydannus is Anxiety, Audee is Hope and Hobbe is Anger. During the first night Syddanus learns Outsider as the Demon doesn''t neighbours an Outsider.","Jasper and Aki are Faith. Tonight Anxiety learns Minion as neither Demon neighbours a Minion."],"firstNight":74,"firstNightReminder":"Point toward a character type.","otherNight":86,"otherNightReminder":"Point toward a character type.","setup":false,"special":[{"type":"selection","name":"bag-duplicate"}],"image":"https://user-images.klutzbanana.com/c866evminkdpo0ilhbzxdy0t.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/s8yr6wncojd7kf53qzhvaeq0.png"}','published','emotions/anxiety',datetime('now'),datetime('now')),
('anger','Anger','townsfolk','Moll',NULL,NULL,'Emotions','{"slug":"anger","name":"Anger","team":"townsfolk","ability":"Each night, learn a player & their alignment. Until dusk, they might think they''ve been or not been affected by an ability.","creator":"Moll","appearsIn":"Emotions","lede":"Anger brings other emotions.","howToRun":["During the game, you may wake any player marked Angry as if any ability had affected them. (You may wake them in the night in a way having been chosen by this ability would do.)","During setup, mark a player Angry. Each dusk, move the Angry reminder to any player.","Each night, wake Anger. Point to the player marked Anger & give a hand signal for their alignment. Put Anger to sleep."],"examples":["Wildheart is Sadness. On the first night Anger learns Wildheart and a thumbs up.","Jasper is a Dissapointment. On the first night Anger learns Jasper and a thumbs up and Jasper is told they were picked by Happiness even though they were not."],"firstNight":46,"firstNightReminder":"Point to a player & give a thumbs up or thumbs down signal. You may wake that player as if an ability has affected them.","otherNight":70,"otherNightReminder":"Point to a player & give a thumbs up or thumbs down signal. You may wake that player as if an ability has affected them.","reminders":["Angry"],"setup":false,"special":[{"type":"selection","name":"bag-duplicate"}],"image":"https://user-images.klutzbanana.com/hjtr3qm1xkqan7cirupmbbll.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/fhep7dzvl4cx8177cgwjj64d.png"}','published','emotions/anger',datetime('now'),datetime('now')),
('sadness','Sadness','townsfolk','Moll',NULL,NULL,'Emotions','{"slug":"sadness","name":"Sadness","team":"townsfolk","ability":"Each night*, you learn who is dead & choose 1, you learn their character.","creator":"Moll","appearsIn":"Emotions","lede":"Sadness comes with memories of the dead.","howToRun":["Each night except the first, wake Sadness. Point to all dead players. The Sadness points to 1 player you pointed to. Show their character token. Put Sadness to sleep."],"examples":["Nicklas is Fear, the first day Nicklas is executed. Tonight the demon kills Hobbe the Boredom. Sadness learns Nicklas & Hobbe, they choose Hobbe & learn Boredom.","Aki is Grief, the first day Aki is executed. Tonight the Demon kills Swampert, a Dissapointment. Sadness learns Swampert & Aki, they choose Aki & learn Grief."],"firstNight":0,"otherNight":86,"otherNightReminder":"Show a character token of a dead player.","setup":false,"special":[{"type":"selection","name":"bag-duplicate"}],"image":"https://user-images.klutzbanana.com/v1nzok3qhbdib70u7u66ahiy.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/bip98r97g6023u5mgk6d1ac7.png"}','published','emotions/sadness',datetime('now'),datetime('now')),
('grief','Grief','townsfolk','Moll',NULL,NULL,'Emotions','{"slug":"grief","name":"Grief","team":"townsfolk","ability":"Each night*, you learn todays executee neighbours (not Travellers) 1) a Minion, 2) a Demon, or 3) both.","creator":"Moll","appearsIn":"Emotions","lede":"You''ll show the fallen your Grief.","howToRun":["If a player dies by execution, put the Grief''s Executee reminder token by the dead player''s character token.","Each night except the first, if a player is marked Executee, wake Grief.","If the player marked Executee neighbours neither a Demon nor a Minion, give a 0 finger signal.","If the player marked Executee neighbours a Minion but no Demon, give a 1 finger signal.","If the player marked Executee neighbours a Demon but no Minion, give a 2 finger signal.","If the player marked Executee neighbours a Demon & a Minion, give a 3 finger signal.","Put Grief to sleep & remove the Executee reminder."],"examples":["Lucifer is Hope neighbouring Hobbe and Nicklas, Boredom and Gratitude respectively. Today Nicklas is executed. That night Grief learns 2 because the executed player neighbours the Demon.","Audee is Faith thinks they''re Grief. They neighbour Jasper the Anger. On the first day Jasper is executed. That night Audee learns a 1, as their information is arbitrary."],"firstNight":0,"otherNight":86,"otherNightReminder":"If a player was executed today: Give a finger signal.","reminders":["Executee"],"setup":false,"special":[{"type":"selection","name":"bag-duplicate"}],"image":"https://user-images.klutzbanana.com/jaf50y13x2ruuafa3etzy533.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/we46tr436gx990rf50f9hyz7.png"}','published','emotions/grief',datetime('now'),datetime('now')),
('disappointment','Disappointment','outsider','Moll',NULL,NULL,'Emotions','{"slug":"disappointment","name":"Disappointment","team":"outsider","ability":"You think you are a Minion, but you are not.","creator":"Moll","appearsIn":"Emotions","lede":"Dissapointment is simply Dissapointing.","howToRun":["While setting up the game, before putting character tokens in the bag, remove the Dissapointment token and add a Minion character token.","During setup, put the Dissapointment''s IS A DISSAPOINTMENT reminder token by any Minion character token, changing that player''s character to the Dissapointment. They are now an Outsider, and do not have the ability of this Minion character. (But they think they do.)","During the game, act as if the Dissapointment is actually this Minion character. (If that character would wake to act at night, the Dissapointment wakes to act. If their ability would give them information, you can give false information to them if you wish.)"],"examples":["When the bag is made, Dissapointment was replaced with an Excitement token. When the tokens are passed out Nicklas draws this one. On the first night he chooses a player,  that player is not told they have been chosen by the Excitement, as Nicklas is not the Excitement."],"firstNight":0,"otherNight":0,"remindersGlobal":["Is a Disappointment"],"setup":true,"special":[{"type":"selection","name":"bag-disabled"},{"type":"reveal","name":"replace-character"}],"image":"https://user-images.klutzbanana.com/ggxgi674fx4figcocffb6v9x.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/yxfxrapyjymh95u4xd6xzo1u.png"}','published','emotions/disappointment',datetime('now'),datetime('now')),
('boredom','Boredom','outsider','Moll',NULL,NULL,'Emotions','{"slug":"boredom","name":"Boredom","team":"outsider","ability":"Your neighbours might think they have been or not been affected by abilities.","creator":"Moll","appearsIn":"Emotions","lede":"Boredom doesn''t want a boring game.","howToRun":["During the game, you may act as if Boredoms neighbours were affected by a another ability. (You may wake them in the night in a way having been chosen by this ability would do.)  If any of Boredoms neighbours would learn they''re affected by an ability, you may choose for them not to."],"examples":["Aki is Sadness neighbouring Boredom. On the first night Aki learns they were chosen by Happiness, even though they weren''t.","Nicklas is the Dissapointment neighbouring Boredom. On the first night Nicklas learns they were chosen by Excitement, even though they weren''t. The next day Boredom is executed. That night Nicklas is not told they were chosen by anyone, cause they weren''t.","Wildheart is Guilt neighbouring Boredom. On the second night Wildheart is chosen by Excitement but doesn''t learn this. Their info tonight is still poisoned."],"firstNight":0,"otherNight":0,"reminders":["Bored","Bored"],"setup":false,"special":[{"type":"selection","name":"bag-duplicate"}],"image":"https://user-images.klutzbanana.com/pl4bqvaxanq48im0mnwu1lli.png","curata":false,"imageAlt":"https://user-images.klutzbanana.com/r5pi9uv4486f940owj2rhu3r.png"}','published','emotions/boredom',datetime('now'),datetime('now'));
